const currentEnv = this.$env.current.name;
const localEndpoint = "http://localhost:8080";
const stagingEndpoint = "https://toro292.et.martiniserver.com";
const prodEndpoint = "https://toro287.et.martiniserver.com";
const payrollAppApiPath = "/api/lonti_app_payroll/1.0";

const getApiUrl = (base) => base.concat(payrollAppApiPath);

if (currentEnv === "staging") {
  this.serverUrl = getApiUrl(stagingEndpoint);
  this.payrollAppApi.setServerUrl(this.serverUrl);
} else if (currentEnv === "prod") {
  this.serverUrl = getApiUrl(prodEndpoint);
  this.payrollAppApi.setServerUrl(this.serverUrl);
} else {
  this.serverUrl = getApiUrl(localEndpoint);
  this.payrollAppApi.setServerUrl(this.serverUrl);
}
